"""Fail-closed integration of global cosmetic rules into upstream uBO Lite.
Only the element picker and the existing cosmetic-filter registration path are
changed. Global filters are stored in Lite-compatible site.* storage, counted
and edited in My filters, and respect filtering modes and cosmetic exceptions.
"""
from pathlib import Path

def replace_once(path: Path, before: str, after: str) -> None:
    source = path.read_text("utf-8")
    if source.count(before) != 1:
        raise RuntimeError(f"Global picker upstream anchor changed: {path}: {before[:85]!r}")
    path.write_text(source.replace(before, after), "utf-8")

def patch_global_picker(extension: Path) -> None:
    replace_once(extension / "picker-ui.html", "    <button id=\"create\" type=\"button\" class=\"preferred\" disabled data-i18n=\"pickerCreate\"><span class=\"hover\"></span></button>", "    <button id=\"create-all\" type=\"button\" disabled data-i18n=\"muPickerCreateForAllWebsites\"><span class=\"hover\"></span></button>\n    <button id=\"create\" type=\"button\" class=\"preferred\" disabled data-i18n=\"pickerCreate\"><span class=\"hover\"></span></button>")
    replace_once(extension / "js/picker-ui.js", "        dom.attr('#create', 'disabled', '');", "        dom.attr('#create', 'disabled', '');\n        dom.attr('#create-all', 'disabled', '');")
    replace_once(extension / "js/picker-ui.js", "        dom.attr('#create', 'disabled', null);", "        dom.attr('#create', 'disabled', null);\n        dom.attr('#create-all', 'disabled', null);")
    replace_once(extension / "js/picker-ui.js", "async function onCreateClicked() {", "async function onCreateClicked(allWebsites = false) {")
    replace_once(extension / "js/picker-ui.js", "        hostname: toolOverlay.url.hostname,\n        selectors: [ selector ],", "        hostname: allWebsites ? '*' : toolOverlay.url.hostname,\n        selectors: [ selector ],")
    replace_once(extension / "js/picker-ui.js", "    dom.on('#create', 'click', ( ) => { onCreateClicked(); });", "    dom.on('#create-all', 'click', ( ) => { onCreateClicked(true); });\n    dom.on('#create', 'click', ( ) => { onCreateClicked(); });")
    replace_once(extension / "js/filter-manager.js", "export async function customFiltersFromHostname(hostname) {", "export async function customFiltersFromHostname(hostname, includeGlobal = true) {")
    replace_once(extension / "js/filter-manager.js", "    const results = await Promise.all(promises);\n    const out = [];", "    if ( includeGlobal && hostname !== '*' ) {\n        promises.push(readFromStorage('site.*'));\n    }\n    const results = await Promise.all(promises);\n    const out = [];")
    replace_once(extension / "js/filter-manager.js", "    return out.sort();", "    return Array.from(new Set(out)).sort();")
    replace_once(extension / "js/filter-manager.js", "    const selectors = await customFiltersFromHostname(hostname);\n    return selectors?.length ?? 0;", "    // The unpicker is scoped to the website: global rules are edited in My filters.\n    const selectors = await customFiltersFromHostname(hostname, false);\n    return selectors?.length ?? 0;")
    replace_once(extension / "js/filter-manager.js", "    const { none } = context.filteringModeDetails;\n    let hostnames = Array.from(customFilters.keys());\n    let excludeHostnames = [];\n    if ( none.has('all-urls') ) {\n        const { basic, optimal, complete } = context.filteringModeDetails;\n        hostnames = intersectHostnameIters(hostnames, [\n            ...basic, ...optimal, ...complete\n        ]);\n    } else if ( none.size !== 0 ) {\n        hostnames = [ ...subtractHostnameIters(hostnames, none) ];\n        excludeHostnames = Array.from(none);\n    }\n    hostnames = hostnames.filter(a =>\n        customFilters.get(a).some(a => isCSS(a) || isProcedural(a))\n    );\n    if ( hostnames.length === 0 ) { return; }", "    const { none } = context.filteringModeDetails;\n    const hasGlobalFilters = customFilters.get('*')?.some(a =>\n        isCSS(a) || isProcedural(a)\n    ) ?? false;\n    let hostnames = Array.from(customFilters.keys());\n    let excludeHostnames = [];\n    if ( none.has('all-urls') ) {\n        const { basic, optimal, complete } = context.filteringModeDetails;\n        const permitted = [ ...basic, ...optimal, ...complete ];\n        // A global filter must still honor the per-site permission modes:\n        // only register it on sites the user explicitly enabled.\n        hostnames = intersectHostnameIters(\n            hostnames.filter(hn => hn !== '*'), permitted\n        );\n        if ( hasGlobalFilters ) { hostnames.push(...permitted); }\n    } else if ( none.size !== 0 ) {\n        hostnames = [ ...subtractHostnameIters(hostnames, none) ];\n        excludeHostnames = Array.from(none);\n    }\n    hostnames = Array.from(new Set(hostnames.filter(hn =>\n        (none.has('all-urls') && hasGlobalFilters) ||\n        customFilters.get(hn)?.some(a => isCSS(a) || isProcedural(a))\n    )));\n    if ( hostnames.length === 0 ) { return; }")
    replace_once(extension / "js/background.js", "    case 'customFiltersFromHostname':\n        return customFiltersFromHostname(request.hostname);", "    case 'customFiltersFromHostname':\n        // Keep the unpicker site-scoped; global rules belong to My filters.\n        return customFiltersFromHostname(request.hostname, false);")
